163:     private final ConcurrentLinkedQueue<EventWithSubscriber> queue = new ConcurrentLinkedQueue<>();
164: 
165:     @Override
166:     void dispatch(Object event, Iterator<Subscriber> subscribers) {
167:       checkNotNull(event);
168:       while (subscribers.hasNext()) {
169:         queue.add(new EventWithSubscriber(event, subscribers.next()));
170:       }
171: 
172:       EventWithSubscriber e;
173:       while ((e = queue.poll()) != null) {
174:         e.subscriber.dispatchEvent(e.event);
175:       }
176:     }
