178:     private static final class EventWithSubscriber {
179:       private final Object event;
180:       private final Subscriber subscriber;
181: 
182:       private EventWithSubscriber(Object event, Subscriber subscriber) {
183:         this.event = event;
184:         this.subscriber = subscriber;
185:       }
186:     }
187:   }
